              { en: "Reference: Nurlanovna, A. (2023). Education in Central Asia. Astana University Press.", ru: "Запись: Nurlanovna, A. (2023). Education in Central Asia. Astana University Press.", kk: "Жазба: Nurlanovna, A. (2023). Education in Central Asia. Astana University Press." }
